const s = $('Load Settings').first().json;
const NL = String.fromCharCode(10);
const tz = s.timezone || 'America/Chicago';
const cur = s.currency || '$';
const since = Date.now() - 86400000;
const ms = v => (v ? new Date(v).getTime() : 0);
const fmtPhone = p => {
  const d = String(p || '').split('').filter(c => c >= '0' && c <= '9').join('').slice(-10);
  return d.length === 10 ? '(' + d.slice(0, 3) + ') ' + d.slice(3, 6) + '-' + d.slice(6) : String(p || '');
};
const when = v => DateTime.fromMillis(ms(v)).setZone(tz).toFormat('ccc h:mm a');
const money = n => cur + Math.round(Number(n) || 0).toLocaleString('en-US');

const calls = $('Calls Today').all().map(i => i.json).filter(r => r && r.call_id && ms(r.at) >= since);
const leads = $('Leads Today').all().map(i => i.json).filter(r => r && r.lead_id && ms(r.created_at) >= since);
const missed = calls.filter(c => c.outcome !== 'answered');
const texted = calls.filter(c => c.text_back_seconds !== null && c.text_back_seconds !== undefined);
const replied = leads.filter(l => l.first_reply_at);
const booked = leads.filter(l => l.status === 'booked');
const value = booked.reduce((a, l) => a + (Number(l.value) || 0), 0);
const needs = leads.filter(l => (l.urgent || l.needs_call) && !l.ack && !['lost', 'opted_out'].includes(l.status));
const quiet = leads.filter(l => ['texted', 'no_reply'].includes(l.status));
const avg = texted.length ? Math.round(texted.reduce((a, c) => a + Number(c.text_back_seconds), 0) / texted.length) : 0;

const lines = [
  'Hi ' + s.ownerName + ',',
  '',
  'Here is what happened with missed calls in the last 24 hours.',
  '',
  'Calls: ' + calls.length + ' (' + (calls.length - missed.length) + ' answered, ' + missed.length + ' missed)',
  'Texted back: ' + texted.length + (avg ? ', ' + avg + ' seconds after the call on average' : ''),
  'Replied: ' + replied.length,
  'Booked: ' + booked.length + ', worth about ' + money(value),
  ''
];
if (needs.length) {
  lines.push('Still needs you:');
  needs.forEach(l => lines.push('- ' + (l.name || fmtPhone(l.phone)) + ', ' + (l.urgent ? 'emergency: ' + (l.issue || 'no details') : 'asked for a call back') + ', ' + fmtPhone(l.phone)));
  lines.push('');
}
if (booked.length) {
  lines.push('New jobs:');
  booked.forEach(l => lines.push('- ' + when(l.slot) + ': ' + (l.issue || 'Job') + ' for ' + (l.name || fmtPhone(l.phone)) + ' in ' + (l.zip || 'the area') + ', ' + money(l.value) + (l.booked_by === 'ai' ? ', booked by the AI' : '')));
  lines.push('');
}
if (quiet.length) {
  lines.push('No reply yet: ' + quiet.map(l => fmtPhone(l.phone)).join(', '));
  lines.push('');
}
lines.push('Missed Call Text-Back');

return [{ json: {
  to: s.ownerEmail,
  subject: 'Missed calls today: ' + missed.length + ' missed, ' + booked.length + ' booked (' + money(value) + ')',
  message: lines.join(NL)
} }];
